local GENE_POOL_ID = 0

---预下载抽奖请求回调处理
function PreDownloadCatHomeDialog:PreDownloadCallResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    local data = checkTable(response.data)
    local geneId = checkInt(data.geneId)
    local genes = ''
    local isNew = PreDownloadMgr:AddCatGene(geneId)
    if Config.DEBUG then
        geneId = GENE_POOL_ID
        GENE_POOL_ID = GENE_POOL_ID + 1
        if GENE_POOL_ID > 40 then
            GENE_POOL_ID = 1
        end
    end

    ---@type PreDownloadCatPoolVo[]
    local catPoolVos = CfUtils.GetWholeVo(AutoIds.IdSetting2658, "PreDownloadCatPoolVo")
    for _, catPoolVo in ipairs(catPoolVos) do
        if catPoolVo.geneId == geneId then
            genes = catPoolVo.appoint
            break
        end
    end
    -- 开始抽卡
    UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationGetCatPopup, parameters = {viewType = 3, geneId = geneId, genes = genes, isNew = isNew}},
            {{id = Constants.UITypeIds.PreDownloadCatMainDialog}}
    )

    CfUtils.SetTopActive(false)
end

---发现按钮点击回调
function PreDownloadCatHomeDialog:BtnDiscoverOnClickHandler()
    GameUtils.Request(Interfaces.PreDownloadCall, {}, Bind(self, self.PreDownloadCallResponseHandler))
end

---图鉴按钮点击回调
function PreDownloadCatHomeDialog:BtnCheckOnClickHandler()
