---刷新个人奖励
function PreDownloadCatHomeDialog:RefreshPersonalRewards()
    local targetNum = checkInt(PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsKeyType.THEME_TARGET_NUM))
    local rewardGoodsId = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsKeyType.REWARD_GOODS_ID)
    local rewardGoodsNum = PreDownloadUtils.GetParamsVoValue(PreDownloadConstants.ParamsKeyType.REWARD_GOODS_NUM)
    local currentNum = table.count(PreDownloadMgr:GetCatGenes())
    
    CfUtils.RefeshGoodGo(self.PersonalRewardsGoodsNode, rewardGoodsId, rewardGoodsNum, 1, nil, function()
        GameUtils.ShowCommonGoodsTipsBoard(self.PersonalRewardsGoodsNode, rewardGoodsId, false)
    end)
    CfUtils.FillText(self.TextTitle, localize('发现猫球 <size=40>_num_</size>个主题基因', {_num_ = targetNum}))
    CfUtils.FillText(self.TxtNumber, string.format('(%d/%d)', math.min(currentNum, targetNum), targetNum))
    KTool.SetActive(self.PersonalImgFinish, currentNum >= targetNum)
end
--endregion private

return PreDownloadCatHomeDialog